import{_ as o,a0 as s,w as p,s as d,ao as r,I as t,x as e,a1 as n,A as l}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const g=JSON.parse('{"title":"Python 高級圖像處理 | LCTT x X-CMD","titleTemplate":false,"description":"Python 高級圖像處理 | LCTT (201608) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Python 高級圖像處理 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Python 高級圖像處理 | LCTT (201608) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201608/20160623 Advanced Image Processing with Python","title":"Python 高級圖像處理","tag":"201608","desc":""},"relativePath":"201608/20160623 Advanced Image Processing with Python.md","filePath":"[post].md"}'),h={name:"201608/20160623 Advanced Image Processing with Python.md"};function u(f,a,b,m,P,S){const i=s("Link");return p(),d("div",null,[a[30]||(a[30]=r('<h1 id="python-高級圖像處理" tabindex="-1">Python 高級圖像處理 <a class="header-anchor" href="#python-高級圖像處理" aria-label="Permalink to “Python 高級圖像處理”">​</a></h1><p><img src="http://www.cuelogic.com/blog/wp-content/uploads/2016/06/Image-Search-Engine.png" alt=""></p><p>構建圖像搜索引擎並不是一件容易的任務。這裏有幾個概念、工具、想法和技術需要實現。主要的圖像處理概念之一是逆圖像查詢(RIQ：reverse image querying)。Google、Cloudera、Sumo Logic 和 Birst 等公司在使用逆圖像搜索中名列前茅。通過分析圖像和使用數據挖掘 RIQ 提供了很好的洞察分析能力。</p><h3 id="頂級公司與逆圖像搜索" tabindex="-1">頂級公司與逆圖像搜索 <a class="header-anchor" href="#頂級公司與逆圖像搜索" aria-label="Permalink to “頂級公司與逆圖像搜索”">​</a></h3><p>有很多頂級的技術公司使用 RIQ 來取得了不錯的收益。例如：在 2014 年 Pinterest 第一次帶來了視覺搜索。隨後在 2015 年發佈了一份白皮書，披露了其架構。逆圖像搜索讓 Pinterest 獲得了時尚品的視覺特徵，並可以顯示相似產品的推薦。</p><p>眾所周知，谷歌圖片使用逆圖像搜索允許用户上傳一張圖片然後搜索相關聯的圖片。通過使用先進的算法對提交的圖片進行分析和數學建模，然後和谷歌資料庫中無數的其他圖片進行比較得到相似的結果。</p><p><strong>這是 OpenCV 2.4.9 特徵比較報告一個圖表：</strong></p><p><img src="http://www.cuelogic.com/blog/wp-content/uploads/2016/06/search-engine-graph.jpg" alt=""></p><h3 id="算法-python庫" tabindex="-1">算法 &amp; Python庫 <a class="header-anchor" href="#算法-python庫" aria-label="Permalink to “算法 &amp; Python庫”">​</a></h3><p>在我們使用它工作之前，讓我們過一遍構建圖像搜索引擎的 Python 庫的主要元素：</p><h3 id="專利算法" tabindex="-1">專利算法 <a class="header-anchor" href="#專利算法" aria-label="Permalink to “專利算法”">​</a></h3><h4 id="尺度不變特徵變換-sift-scale-invariant-feature-transform-算法" tabindex="-1">尺度不變特徵變換（SIFT - Scale-Invariant Feature Transform）算法 <a class="header-anchor" href="#尺度不變特徵變換-sift-scale-invariant-feature-transform-算法" aria-label="Permalink to “尺度不變特徵變換（SIFT - Scale-Invariant Feature Transform）算法”">​</a></h4>',12)),t("ol",null,[t("li",null,[a[1]||(a[1]=e("帶有非自由功能的一個專利技術，利用圖像識別符，以識別相似圖像，甚至那些來自不同的角度，大小，深度和尺度的圖片，也會被包括在搜索結果中。",-1)),n(i,{href:"https://www.youtube.com/watch?v=NPcMS49V5hg"},{default:l(()=>[...a[0]||(a[0]=[e("點擊這裏",-1)])]),_:1}),a[2]||(a[2]=e("查看 SIFT 詳細視頻。",-1))]),a[6]||(a[6]=t("li",null,"SIFT 能與從許多圖片中提取了特徵的大型資料庫正確地匹配搜索條件。",-1)),t("li",null,[a[4]||(a[4]=e("能匹配不同視角的相同圖像和匹配不變特徵來獲得搜索結果是 SIFT 的另一個特徵。瞭解更多關於尺度不變",-1)),n(i,{href:"https://www.cs.ubc.ca/~lowe/papers/ijcv04.pdf"},{default:l(()=>[...a[3]||(a[3]=[e("關鍵點",-1)])]),_:1}),a[5]||(a[5]=e("。",-1))])]),a[31]||(a[31]=t("h4",{id:"加速魯棒特徵-surf-speeded-up-robust-features-算法",tabindex:"-1"},[e("加速魯棒特徵（SURF - Speeded Up Robust Features）算法 "),t("a",{class:"header-anchor",href:"#加速魯棒特徵-surf-speeded-up-robust-features-算法","aria-label":"Permalink to “加速魯棒特徵（SURF - Speeded Up Robust Features）算法”"},"​")],-1)),t("ol",null,[t("li",null,[n(i,{href:"http://docs.opencv.org/3.0-beta/doc/py_tutorials/py_feature2d/py_surf_intro/py_surf_intro.html"},{default:l(()=>[...a[7]||(a[7]=[e("SURF",-1)])]),_:1}),a[8]||(a[8]=e(" 也是一種帶有非自由功能的專利技術，而且還是一種“加速”的 SIFT 版本。不像 SIFT，SURF 接近於帶有箱式過濾器（Box Filter）的高斯拉普拉斯算子（Laplacian of Gaussian）。",-1))]),a[11]||(a[11]=t("li",null,"SURF 依賴於黑塞矩陣（Hessian Matrix）的位置和尺度。",-1)),a[12]||(a[12]=t("li",null,"在許多應用中，旋轉不變性不是一個必要條件，所以不按這個方向查找加速了處理。",-1)),a[13]||(a[13]=t("li",null,"SURF 包括了幾種特性，提升了每一步的速度。SIFT 在旋轉和模糊化方面做的很好，比 SIFT 的速度快三倍。然而它不擅長處理照明和變換視角。",-1)),t("li",null,[a[10]||(a[10]=e("OpenCV 程序功能庫提供了 SURF 功能，SURF.compute() 和 SURF.Detect() 可以用來找到描述符和要點。閲讀更多關於SURF",-1)),n(i,{href:"http://www.vision.ee.ethz.ch/~surf/eccv06.pdf"},{default:l(()=>[...a[9]||(a[9]=[e("點擊這裏",-1)])]),_:1})])]),a[32]||(a[32]=r('<h3 id="開源算法" tabindex="-1">開源算法 <a class="header-anchor" href="#開源算法" aria-label="Permalink to “開源算法”">​</a></h3><h4 id="kaze-算法" tabindex="-1">KAZE 算法 <a class="header-anchor" href="#kaze-算法" aria-label="Permalink to “KAZE 算法”">​</a></h4><ol><li>KAZE是一個開源的非線性尺度空間的二維多尺度和新的特徵檢測和描述算法。在加性算子分裂（Additive Operator Splitting, AOS）和可變電導擴散中的有效技術被用來建立非線性尺度空間。</li><li>多尺度圖像處理的基本原理很簡單：創建一個圖像的尺度空間，同時用正確的函數過濾原始圖像，以提高時間或尺度。</li></ol><h4 id="加速的-kaze-akaze-accelerated-kaze-算法" tabindex="-1">加速的 KAZE（AKAZE - Accelerated-KAZE) 算法 <a class="header-anchor" href="#加速的-kaze-akaze-accelerated-kaze-算法" aria-label="Permalink to “加速的 KAZE（AKAZE - Accelerated-KAZE) 算法”">​</a></h4><ol><li>顧名思義，這是一個更快的圖像搜索方式，它會在兩幅圖像之間找到匹配的關鍵點。AKAZE 使用二進制描述符和非線性尺度空間來平衡精度和速度。</li></ol><h4 id="二進制魯棒性不變尺度可變關鍵點-brisk-binary-robust-invariant-scalable-keypoints-算法" tabindex="-1">二進制魯棒性不變尺度可變關鍵點（BRISK - Binary Robust Invariant Scalable Keypoints) 算法 <a class="header-anchor" href="#二進制魯棒性不變尺度可變關鍵點-brisk-binary-robust-invariant-scalable-keypoints-算法" aria-label="Permalink to “二進制魯棒性不變尺度可變關鍵點（BRISK - Binary Robust Invariant Scalable Keypoints) 算法”">​</a></h4><ol><li>BRISK 非常適合關鍵點的描述、檢測與匹配。</li><li>是一種高度自適應的算法，基於尺度空間 FAST 的快速檢測器和一個位字符串描述符，有助於顯著加快搜索。</li><li>尺度空間關鍵點檢測與關鍵點描述幫助優化當前相關任務的性能。</li></ol><h4 id="快速視網膜關鍵點-freak-fast-retina-keypoint" tabindex="-1">快速視網膜關鍵點（FREAK - Fast Retina Keypoint） <a class="header-anchor" href="#快速視網膜關鍵點-freak-fast-retina-keypoint" aria-label="Permalink to “快速視網膜關鍵點（FREAK - Fast Retina Keypoint）”">​</a></h4><ol><li>這個新的關鍵點描述的靈感來自人的眼睛。通過圖像強度比能有效地計算一個二進制串級聯。FREAK 算法相比 BRISK、SURF 和 SIFT 算法可以更快的計算與內存負載較低。</li></ol><h4 id="定向-fast-和旋轉-brief-orb-oriented-fast-and-rotated-brief" tabindex="-1">定向 FAST 和旋轉 BRIEF（ORB - Oriented FAST and Rotated BRIEF） <a class="header-anchor" href="#定向-fast-和旋轉-brief-orb-oriented-fast-and-rotated-brief" aria-label="Permalink to “定向 FAST 和旋轉 BRIEF（ORB - Oriented FAST and Rotated BRIEF）”">​</a></h4><ol><li>快速的二進制描述符，ORB 具有抗噪聲和旋轉不變性。ORB 建立在 FAST 關鍵點檢測器和 BRIEF 描述符之上，有成本低、性能好的元素屬性。</li><li>除了快速和精確的定位元件，有效地計算定向的 BRIEF，分析變動和麪向 BRIEF 特點相關，是另一個 ORB 的特徵。</li></ol><h3 id="python庫" tabindex="-1">Python庫 <a class="header-anchor" href="#python庫" aria-label="Permalink to “Python庫”">​</a></h3><h4 id="opencv" tabindex="-1">OpenCV <a class="header-anchor" href="#opencv" aria-label="Permalink to “OpenCV”">​</a></h4><ol><li>OpenCV 支持學術和商業用途，它是一個開源的機器學習和計算機視覺庫，OpenCV 便於組織利用和修改代碼。</li><li>超過 2500 個優化的算法，包括當前最先進的機器學習和計算機視覺算法服務與各種圖像搜索--人臉檢測、目標識別、攝像機目標跟蹤，從圖像資料庫中尋找類似圖像、眼球運動跟隨、風景識別等。</li><li>像谷歌，IBM，雅虎，索尼，本田，微軟和英特爾這樣的大公司廣泛的使用 OpenCV。</li><li>OpenCV 擁有 python，java，C，C++ 和 MATLAB 接口，同時支持 Windows，Linux，Mac OS 和 Android。</li></ol><h4 id="python-圖像庫-pil" tabindex="-1">Python 圖像庫 （PIL） <a class="header-anchor" href="#python-圖像庫-pil" aria-label="Permalink to “Python 圖像庫 （PIL）”">​</a></h4><ol><li>Python 圖像庫（PIL）支持多種文件格式，同時提供圖像處理和圖形解決方案。開源的 PIL 為你的 Python解釋器添加了圖像處理能力。</li><li>標準的圖像處理能力包括圖像增強、透明和遮罩處理、圖像過濾、像素操作等。</li></ol>',16)),t("p",null,[a[15]||(a[15]=e("詳細的數據和圖表，請看",-1)),n(i,{href:"https://docs.google.com/spreadsheets/d/1gYJsy2ROtqvIVvOKretfxQG_0OsaiFvb7uFRDu5P8hw/edit#gid=10"},{default:l(()=>[...a[14]||(a[14]=[e("這裏",-1)])]),_:1}),a[16]||(a[16]=e("的 OpenCV 2.4.9 特徵比較報告。",-1))]),a[33]||(a[33]=r('<h3 id="構建圖像搜索引擎" tabindex="-1">構建圖像搜索引擎 <a class="header-anchor" href="#構建圖像搜索引擎" aria-label="Permalink to “構建圖像搜索引擎”">​</a></h3><p>圖像搜索引擎可以從預置的圖像庫選擇相似的圖像。其中最受歡迎的是谷歌的著名的圖像搜索引擎。對於初學者來説，有不同的方法來建立這樣的系統。提幾個如下：</p><ol><li>採用圖像提取、圖像描述提取、元數據提取和搜索結果提取，建立圖像搜索引擎。</li><li>定義你的圖像描述符，數據集索引，定義你的相似性度量，然後進行搜索和排名。</li><li>選擇要搜索的圖像，選擇用於進行搜索的目錄，搜索所有圖片的目錄，創建圖片特徵索引，評估搜索圖片的相同特徵，匹配搜索的圖片並獲得匹配的圖片。</li></ol><p>我們的方法基本上從比較灰度版本的圖像，逐漸演變到複雜的特徵匹配算法如 SIFT 和 SURF，最後採用的是開源的解決方案 BRISK 。所有這些算法都提供了有效的結果，但在性能和延遲有細微變化。建立在這些算法上的引擎有許多應用，如分析流行統計的圖形數據，在圖形內容中識別對象，等等。</p><p><strong>舉例</strong>：一個 IT 公司為其客户建立了一個圖像搜索引擎。因此，如果如果搜索一個品牌的標誌圖像，所有相關的品牌形象也應該顯示在搜索結果。所得到的結果也能夠被客户用於分析，使他們能夠根據地理位置估計品牌知名度。但它還比較年輕，RIQ（反向圖像搜索）的潛力尚未被完全挖掘利用。</p><p>這就結束了我們的文章，使用 Python 構建圖像搜索引擎。瀏覽我們的Blog部分來查看最新的編程技術。</p><p>數據來源：OpenCV 2.4.9 特徵比較報告（computer-vision-talks.com）</p><p>(感謝 Ananthu Nair 的指導與補充)</p><hr>',9)),t("p",null,[a[18]||(a[18]=e("via: ",-1)),n(i,{href:"http://www.cuelogic.com/blog/advanced-image-processing-with-python/"},{default:l(()=>[...a[17]||(a[17]=[e("http://www.cuelogic.com/blog/advanced-image-processing-with-python/",-1)])]),_:1})]),t("p",null,[a[22]||(a[22]=e("作者：",-1)),n(i,{href:"http://www.cuelogic.com/blog/author/snehith-kumbla/"},{default:l(()=>[...a[19]||(a[19]=[e("Snehith Kumbla",-1)])]),_:1}),a[23]||(a[23]=e(" 譯者：",-1)),n(i,{href:"https://github.com/Johnny-Liao"},{default:l(()=>[...a[20]||(a[20]=[e("Johnny-Liao",-1)])]),_:1}),a[24]||(a[24]=e(" 校對：",-1)),n(i,{href:"https://github.com/wxy"},{default:l(()=>[...a[21]||(a[21]=[e("wxy",-1)])]),_:1})]),t("p",null,[a[27]||(a[27]=e("本文由 ",-1)),n(i,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...a[25]||(a[25]=[e("LCTT",-1)])]),_:1}),a[28]||(a[28]=e(" 原創編譯，",-1)),n(i,{href:"https://linux.cn/"},{default:l(()=>[...a[26]||(a[26]=[e("Linux中國",-1)])]),_:1}),a[29]||(a[29]=e(" 榮譽推出",-1))])])}const I=o(h,[["render",u]]);export{g as __pageData,I as default};
